76	         to_cpu_sbuff.tuser_src = from_dpe_sbuff.tuser_src;
77	         to_cpu_sbuff.tuser_dst = from_dpe_sbuff.tuser_dst;
78	      end else begin
79	         to_cpu_sbuff.tvalid = 1'b0;
80	         to_cpu_sbuff.tdata = '0;
81	         to_cpu_sbuff.tkeep = '0;
82	         to_cpu_sbuff.tlast = '0;
83	         to_cpu_sbuff.tuser_bypass_all = 1'b0;
84	         to_cpu_sbuff.tuser_bypass_stage = 1'b0;
85	         to_cpu_sbuff.tuser_src = '0;
86	         to_cpu_sbuff.tuser_dst = '0;
87	      end
88	      if (from_dpe_sbuff.tuser_dst == DPE_ADDR_ETH_1 || from_dpe_sbuff.tuser_dst == DPE_ADDR_MCAST_13 || from_dpe_sbuff.tuser_dst == DPE_ADDR_BCAST) begin
