104	         to_eth_1_sbuff.tuser_src = '0;
105	         to_eth_1_sbuff.tuser_dst = '0;
106	      end
107	      if (from_dpe_sbuff.tuser_dst == DPE_ADDR_ETH_2 || from_dpe_sbuff.tuser_dst == DPE_ADDR_MCAST_24 || from_dpe_sbuff.tuser_dst == DPE_ADDR_BCAST) begin
