131	         to_eth_3_sbuff.tuser_bypass_all = from_dpe_sbuff.tuser_bypass_all;
132	         to_eth_3_sbuff.tuser_bypass_stage = from_dpe_sbuff.tuser_bypass_stage;
133	         to_eth_3_sbuff.tuser_src = from_dpe_sbuff.tuser_src;
134	         to_eth_3_sbuff.tuser_dst = from_dpe_sbuff.tuser_dst;
135	      end else begin
