151	         to_eth_4_sbuff.tuser_bypass_stage = from_dpe_sbuff.tuser_bypass_stage;
152	         to_eth_4_sbuff.tuser_src = from_dpe_sbuff.tuser_src;
153	         to_eth_4_sbuff.tuser_dst = from_dpe_sbuff.tuser_dst;
154	      end else begin
