38	//--------------------------------------------------------------------------
39	// Description:
40	//   DPE demultiplexer testbench
41	//==========================================================================
42	
43	`timescale 1ps/1ps
44	
45	module tb;
46	    // Constants
47	    localparam CLK_PERIOD = 12_500;
48	    import dpe_pkg::*;
49	
50	    // Clock and reset signals
51	    logic clk = 0;
52	    logic rst = 1;
53	
54	    // Interfaces
55	    dpe_if from_dpe(.clk(clk), .rst(rst));
56	    dpe_if to_cpu(.clk(clk), .rst(rst));
57	    dpe_if to_eth_1(.clk(clk), .rst(rst));
58	    dpe_if to_eth_2(.clk(clk), .rst(rst));
59	    dpe_if to_eth_3(.clk(clk), .rst(rst));
60	    dpe_if to_eth_4(.clk(clk), .rst(rst));
61	
62	    // Test data type and constants
63	    typedef logic [7:0] test_data_t [6];
64	    typedef test_data_t packet_data_t [6];
65	
66	    const packet_data_t packet_data = '{
67	        '{8'h01, 8'h02, 8'h03, 8'h04, 8'h05, 8'h06},  // to Output 0
68	        '{8'h0B, 8'h0C, 8'h0D, 8'h0E, 8'h00, 8'h00},  // to Output 1
69	        '{8'h15, 8'h16, 8'h17, 8'h18, 8'h19, 8'h00},  // to Output 2
70	        '{8'h1F, 8'h20, 8'h21, 8'h22, 8'h00, 8'h00},  // to Output 3
71	        '{8'h29, 8'h2A, 8'h2B, 8'h2C, 8'h00, 8'h00},  // to Output 4
72	        '{8'h33, 8'h34, 8'h35, 8'h36, 8'h37, 8'h00}   // to all outputs
73	    };
74	
75	    // Clock generation
76	    always #(CLK_PERIOD/2) clk <= ~clk;
77	
78	    // DUT instantiation
79	    dpe_demultiplexer DUT (
80	        .from_dpe(from_dpe),
81	        .to_cpu(to_cpu),
82	        .to_eth_1(to_eth_1),
83	        .to_eth_2(to_eth_2),
84	        .to_eth_3(to_eth_3),
85	        .to_eth_4(to_eth_4)
86	    );
87	
88	    // Main stimulus process
89	    initial begin
90	        // Initialize input interface
91	        from_dpe.tvalid = 0;
92	        from_dpe.tlast = 0;
93	        from_dpe.tkeep = '0;
94	        from_dpe.tdata = '0;
95	
96	        // Reset assertion
97	        #(CLK_PERIOD * 4);
98	        @(posedge clk);
99	        #1ps;
100	        rst = 0;
101	        #(CLK_PERIOD);
102	
103	        // Input stimulus
104	        begin
105	            @(posedge clk);
106	            // Send packet 0
107	            #1ps;
108	            from_dpe.tvalid = 1;
109	            for (int i = 0; i < 6; i++) begin
110	                from_dpe.tuser_bypass_all = 0;
111	                from_dpe.tuser_bypass_stage = 0;
112	                from_dpe.tuser_src = DPE_ADDR_CPU;
113	                from_dpe.tuser_dst = DPE_ADDR_CPU;
114	                from_dpe.tdata = '0;
115	                from_dpe.tdata[7:0] = packet_data[0][i];
116	                from_dpe.tkeep = '1;
117	                from_dpe.tlast = (i == 5);
118	                @(posedge clk);
119	                while (!from_dpe.tready) @(posedge clk);
120	                #1ps;
121	            end
122	            from_dpe.tvalid = 0;
123	            from_dpe.tlast = 0;
124	            // Send packet 1
125	            from_dpe.tvalid = 1;
126	            for (int i = 0; i < 4; i++) begin
127	                from_dpe.tuser_bypass_all = 0;
128	                from_dpe.tuser_bypass_stage = 0;
129	                from_dpe.tuser_src = DPE_ADDR_CPU;
130	                from_dpe.tuser_dst = DPE_ADDR_ETH_1;
131	                from_dpe.tdata = '0;
132	                from_dpe.tdata[7:0] = packet_data[1][i];
133	                from_dpe.tkeep = '1;
134	                from_dpe.tlast = (i == 3);
135	                @(posedge clk);
136	                while (!from_dpe.tready) @(posedge clk);
137	                #1ps;
138	            end
139	            from_dpe.tvalid = 0;
140	            from_dpe.tlast = 0;
141	            // Send packet 2
142	            from_dpe.tvalid = 1;
143	            for (int i = 0; i < 5; i++) begin
144	                from_dpe.tuser_bypass_all = 0;
145	                from_dpe.tuser_bypass_stage = 0;
146	                from_dpe.tuser_src = DPE_ADDR_CPU;
147	                from_dpe.tuser_dst = DPE_ADDR_ETH_2;
148	                from_dpe.tdata = '0;
149	                from_dpe.tdata[7:0] = packet_data[2][i];
150	                from_dpe.tkeep = '1;
151	                from_dpe.tlast = (i == 4);
152	                @(posedge clk);
153	                while (!from_dpe.tready) @(posedge clk);
154	                #1ps;
155	            end
156	            from_dpe.tvalid = 0;
157	            from_dpe.tlast = 0;
158	            // Send packet 3
159	            from_dpe.tvalid = 1;
160	            for (int i = 0; i < 4; i++) begin
161	                from_dpe.tuser_bypass_all = 0;
162	                from_dpe.tuser_bypass_stage = 0;
163	                from_dpe.tuser_src = DPE_ADDR_CPU;
164	                from_dpe.tuser_dst = DPE_ADDR_ETH_3;
165	                from_dpe.tdata = '0;
166	                from_dpe.tdata[7:0] = packet_data[3][i];
167	                from_dpe.tkeep = '1;
168	                from_dpe.tlast = (i == 3);
169	                @(posedge clk);
170	                while (!from_dpe.tready) @(posedge clk);
171	                #1ps;
172	            end
173	            from_dpe.tvalid = 0;
174	            from_dpe.tlast = 0;
175	            // Send packet 4
176	            from_dpe.tvalid = 1;
177	            for (int i = 0; i < 4; i++) begin
178	                from_dpe.tuser_bypass_all = 0;
179	                from_dpe.tuser_bypass_stage = 0;
180	                from_dpe.tuser_src = DPE_ADDR_CPU;
181	                from_dpe.tuser_dst = DPE_ADDR_ETH_4;
